const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch(); const p = await b.newPage();
  await p.goto('file:///Users/vmysla/src/ab-study/arms/calculator-rep-control-02/control/index.html');
  const keys = ['0','1','2','3','.','+','-','*','/','(',')','Enter','key-sign'];
  const found = new Map();
  for (let t = 0; t < 3000 && found.size < 8; t++) {
    const seq = []; const n = 4 + Math.floor(Math.random()*10);
    for (let i = 0; i < n; i++) seq.push(keys[Math.floor(Math.random()*keys.length)]);
    const res = await p.evaluate((seq) => {
      document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape'}));
      document.querySelector('[data-testid="tape-clear"]').click();
      for (const k of seq) {
        if (k === 'key-sign') document.querySelector('[data-testid="key-sign"]').click();
        else document.dispatchEvent(new KeyboardEvent('keydown',{key:k}));
      }
      return { tape: [...document.querySelectorAll('[data-testid="tape-row"]')].map(r => r.innerText.replace(/\n/g,' | ')),
               display: document.querySelector('[data-testid="calc-display"]').textContent };
    }, seq);
    const bad = res.tape.find(r => /\d{11,}/.test(r.replace(/[.\-]/g,'')) );
    if (bad) { const key = bad.replace(/\d/g,'9'); if (!found.has(key)) { found.set(key,1); console.log(seq.join(' '), '=>', JSON.stringify(res.tape), 'display', res.display); } }
  }
  await b.close();
})();
EOF
